-- Reconciles mapper_event with NGC's own rule mapping files (src/main/resources/business_rules/mappings/*-rule-mappings.json).
-- V8 was seeded from the rule engine's TargetEventClassification; NGC's files list further events per category.
-- Rule: the classification decides the mapper class, so events it already places keep that mapper (e.g. the two scheduled-pages
-- events stay with scheduled-pages although the files give them the automated rule set). Events only the files know are added to
-- the mapper whose rule category lists them.

INSERT INTO mapper_event (tag_id, event_type) SELECT id, 'newbusiness.policyenrichment.completed' FROM tag WHERE category = 'MAPPER' AND code = 'policy-page' AND NOT EXISTS (SELECT 1 FROM mapper_event m WHERE m.tag_id = tag.id AND m.event_type = 'newbusiness.policyenrichment.completed');
INSERT INTO mapper_event (tag_id, event_type) SELECT id, 'policy.activationthirtyday.completed' FROM tag WHERE category = 'MAPPER' AND code = 'policy-page' AND NOT EXISTS (SELECT 1 FROM mapper_event m WHERE m.tag_id = tag.id AND m.event_type = 'policy.activationthirtyday.completed');
