UPDATE test_module SET description = 'Policy page (POLPG) letters sent after a policy is activated or issued. NGC mapper: PolicyPageXmlMapper. Events: policy.activation.completed, policy.activationthirtyday.completed, policy.issuance.completed, policy.issuancethirtyday.completed, newbusiness.policyenrichment.completed.' WHERE code = 'policy-page' AND description LIKE 'Policy page (POLPG) letters%';
UPDATE test_module SET description = 'New business letters from BPM events. NGC mapper: NewBusinessLettersXmlMapper. 20 events including newbusiness.transferOfAssets.notification, underwriting decisions, preNote, replacement notices and the umbrella.* application and offer events.' WHERE code = 'new-business' AND description LIKE 'New business letters from BPM events%';
